      "card_ids": ["C01"],
      "claim": "Rolipram is completely absorbed after oral ingestion in humans with an absolute bioavailability of 73 ± 25%, supporting high bioavailability."
    },
    {
      "card_ids": ["C08"],
      "claim": "Deramciclane has an absolute oral bioavailability of 44.3 ± 8.6% in healthy male volunteers after a 30 mg oral solution versus IV, still above the 20% threshold."
    }
  ],
